static decimal Toplam(params decimal[] fiyatlar)
{
    decimal sonuc = 0;
    foreach (decimal fiyat in fiyatlar)
    {
        if (fiyat < 0) continue;
        sonuc += fiyat;
    }
    return sonuc;
}
Console.WriteLine(Toplam(10m, -3m, 20m)); // 30

