static async Task<int> OkuAsync(string yol, CancellationToken token)
{
    string metin = await File.ReadAllTextAsync(yol, token)
        .ConfigureAwait(false);
    return metin.Length;
}
// Çağıran: int uzunluk = await OkuAsync(yol, token);

static Task<int> CallbackOrnegi()
{
    var tcs = new TaskCompletionSource<int>(
        TaskCreationOptions.RunContinuationsAsynchronously);
    ThreadPool.QueueUserWorkItem(_ => tcs.TrySetResult(42));
    return tcs.Task;
}
Console.WriteLine(await CallbackOrnegi()); // 42

