using System.Numerics;
static T Topla<T>(ReadOnlySpan<T> veriler) where T : INumber<T>
{
    T toplam = T.Zero;
    foreach (T x in veriler) toplam += x;
    return toplam;
}
Console.WriteLine(Topla<int>(new int[] { 1, 2, 3 })); // 6

// Basit round-trip özelliği; tam fuzzing altyapısı değildir.
using System.Buffers.Binary;
var rastgele = new Random(42);
byte[] alan = new byte[4];
for (int i = 0; i < 1000; i++)
{
    int sayi = rastgele.Next();
    BinaryPrimitives.WriteInt32BigEndian(alan, sayi);
    if (BinaryPrimitives.ReadInt32BigEndian(alan) != sayi)
        throw new InvalidOperationException("Round-trip bozuldu");
}
Console.WriteLine("1000 örnek doğrulandı");
